/**
 * Personal API token rows. Only a hash of the secret is ever stored; rows
 * mapped out of this module never expose it.
 */
import { and, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { getDb, apiTokens } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { brandId, brandStamp, brandStampOrNull } from "./_mappers";
import type { ApiTokenRow } from "@/server/db";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { ApiToken } from "@/types/api-token";

function toApiToken(row: ApiTokenRow): ApiToken {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    name: row.name,
    scope: row.scope,
    prefix: row.prefix,
    expiresAt: brandStamp(row.expiresAt),
    lastUsedAt: brandStampOrNull(row.lastUsedAt),
    revokedAt: brandStampOrNull(row.revokedAt),
    createdAt: brandStamp(row.createdAt),
  };
}

export interface NewApiToken {
  id: string;
  orgId: OrgId;
  userId: UserId;
  name: string;
  scope: ApiToken["scope"];
  prefix: string;
  tokenHash: string;
  expiresAt: IsoTimestamp;
  createdAt: IsoTimestamp;
}

/**
 * Inserts the token unless the user already holds `maxUsable` usable ones
 * (not revoked, not expired at `now`). Count and insert run in one
 * transaction so concurrent creates cannot overshoot the limit.
 */
export async function insertApiTokenWithinLimit(
  token: NewApiToken,
  maxUsable: number,
  now: IsoTimestamp,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const usable = tx
      .select({ n: sql<number>`count(*)` })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, token.orgId),
          eq(apiTokens.userId, token.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, now),
        ),
      )
      .get();
    if ((usable?.n ?? 0) >= maxUsable) return null;

    const row = tx
      .insert(apiTokens)
      .values({ ...token, lastUsedAt: null, revokedAt: null })
      .returning()
      .get();
    return toApiToken(row);
  });
}

export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  return getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), desc(sql`rowid`))
    .all()
    .map(toApiToken);
}

export async function findApiToken(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/** Lookup by secret hash; global, since the caller does not know the org yet. */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Sets `revokedAt` only if still unrevoked; `null` when nothing changed. */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  now: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: now })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

/** Revokes every unrevoked token of the user in the org; returns those rows. */
export async function revokeAllForUser(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  return getDb()
    .update(apiTokens)
    .set({ revokedAt: now })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .all()
    .map(toApiToken);
}

export async function touchLastUsed(
  orgId: OrgId,
  tokenId: string,
  now: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: now })
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .run();
}
